/** The card layout of SitemapFooter: the brand mark and word, then the link groups in one row, in a rounded card. */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Container } from "../primitives/container/container";
import { Group } from "../primitives/group/group";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { defaults } from "../presets/defaults";
import { cn } from "../utils";
import type { MegaGroup } from "../blocks/mega-menu.types";

export type FooterCardProps = {
  label: string;
  brand: string;
  groups: MegaGroup[];
};

export function FooterCard({ label, brand, groups }: FooterCardProps) {
  return (
    <Block tag="footer" className="py-8" data-testid="site-footer" data-layout="card">
      <Container className={cn(cn("mx-auto w-full px-4", defaults.section.landing), "px-0")} data-slot="container">
        <Box
          className={cn(
            "flex w-full flex-row items-start overflow-hidden bg-muted p-10",
            defaults.footer.card
          )}
          data-testid="footer-card"
        >
          <Group gap="4" align="center" className={cn("h-8 shrink-0", defaults.footer.brand)} data-testid="footer-brand">
            <Inline className="flex size-8 items-center justify-center rounded bg-foreground text-background">
              <LucideIcon name="hexagon" size={16} />
            </Inline>
            <Text size="base" weight="bold">
              {brand}
            </Text>
          </Group>
          <Block tag="nav" className="min-w-0 flex-1" aria-label={label}>
            <Group
              gap="0"
              align="start"
              className={cn("flex w-full flex-nowrap justify-between", defaults.footer.groups)}
              data-testid="footer-groups"
            >
              {(groups ?? []).map((g) => (
                <Stack key={g.id} gap="4" data-testid="group">
                  <Text size="xs" weight="semibold" className="leading-5">
                    {g.title}
                  </Text>
                  <List className="m-0 flex list-none flex-col gap-4 p-0">
                    {(g.links ?? []).map((item) => (
                      <ListItem key={item}>
                        <Link href="#/" variant="default" className="text-xs leading-5 text-muted-foreground">
                          {item}
                        </Link>
                      </ListItem>
                    ))}
                  </List>
                </Stack>
              ))}
            </Group>
          </Block>
        </Box>
      </Container>
    </Block>
  );
}
